var deconfuseRunes = map[rune]bool{
	'0': true, 'O': true, 'o': true, '1': true, 'l': true, 'I': true,
}

func BuildCharsetTable(charsets []FNCharset, deconfuse bool) ([]rune, error) {
	table := make([]rune, 0, len(AlnumChars)+8)
	table = append(table, AlnumChars...)

	for _, cs := range charsets {
		var chars []rune
		switch cs {
		case FNAlnum:
			continue
		case FNSymbolsBasic:
			chars = SymbolsBasicChars
		case FNSymbolsExt:
			chars = SymbolsExtChars
		case FNHanziRare:
			chars = HanziRareChars
		case FNEmoji:
			chars = EmojiChars
		default:
			return nil, errors.New("enc-fn: unknown charset: " + string(cs))
		}
		for _, r := range chars {
			if !containsRune(table, r) {
				table = append(table, r)
			}
		}
	}

	if deconfuse {
		filtered := make([]rune, 0, len(table))
		for _, r := range table {
			if !deconfuseRunes[r] {
				filtered = append(filtered, r)
			}
		}
		if len(filtered) == 0 {
			return nil, errors.New("enc-fn: empty charset after deconfusion")
		}
		table = filtered
	}

	return table, nil
}

func containsRune(slice []rune, r rune) bool {
	for _, s := range slice {
		if s == r {
			return true
		}
	}
	return false
}

func EncodeToCharset(data []byte, table []rune) string {
	if len(data) == 0 {
		return ""
	}
	base := uint64(len(table))
	charWidth := charsetCharWidth(base)
	result := make([]rune, 0, len(data)*charWidth)
	for _, b := range data {
		val := uint64(b)
		digits := make([]rune, charWidth)
		for i := 0; i < charWidth; i++ {
			digits[charWidth-1-i] = table[val%base]
			val /= base
		}
		result = append(result, digits...)
	}
	return string(result)
}

func DecodeFromCharset(s string, table []rune) ([]byte, error) {
	if len(s) == 0 {
		return nil, nil
	}
	base := uint64(len(table))
	charWidth := charsetCharWidth(base)

	runes := []rune(s)
	if len(runes)%charWidth != 0 {
		return nil, ErrFNInvalidFormat
	}

	revMap := make(map[rune]uint64, len(table))
	for i, r := range table {
		revMap[r] = uint64(i)
	}

	data := make([]byte, 0, len(runes)/charWidth)
	for i := 0; i < len(runes); i += charWidth {
		var val uint64
		for j := 0; j < charWidth; j++ {
			ch := runes[i+j]
			v, ok := revMap[ch]
			if !ok {
				return nil, ErrFNCharsetMismatch
			}
			val = val*base + v
		}
		data = append(data, byte(val))
	}
	return data, nil
}

func charsetCharWidth(base uint64) int {
	width := 1
	pow := base
	for pow < 256 {
		pow *= base
		width++
	}
	return width
}

var (
	ErrFNEmptyInput       = errors.New("enc-fn: empty input")
	ErrFNInvalidFormat    = errors.New("enc-fn: invalid format")
	ErrFNChecksumMismatch = errors.New("enc-fn: checksum mismatch")
	ErrFNCorrupt          = errors.New("enc-fn: corrupt data")
	ErrFNCharsetMismatch  = errors.New("enc-fn: charset mismatch")
)
